import React, { Fragment, MutableRefObject, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { createForm, IFormProps, Form, onFormSubmitSuccess } from '@formily/core';
import { toJS } from '@formily/reactive';
import { FormProvider, Observer, observer, ReactFC } from '@formily/react';
import { isNum, isStr, isBool, isFn, applyMiddleware, IMiddleware } from '@formily/shared';
import { Drawer, DrawerProps } from '@arco-design/web-react';
import { usePrefixCls, createPortalProvider, createPortalRoot, loading } from '../__builtins__';

type FormDrawerRenderer = React.ReactElement | ((form: Form) => React.ReactElement);

type DrawerTitle = string | number | React.ReactElement;

type EventType = React.KeyboardEvent<HTMLDivElement> | React.MouseEvent<HTMLDivElement | HTMLButtonElement>;

const isDrawerTitle = (props: any): props is DrawerTitle =>
  isNum(props) || isStr(props) || isBool(props) || React.isValidElement(props);

const getDrawerProps = (props: any): IDrawerProps => {
  if (isDrawerTitle(props)) {
    return {
      title: props,
    };
  } else {
    return props;
  }
};

export interface IFormDrawer {
  forOpen(middleware: IMiddleware<IFormProps>): IFormDrawer;
  open(props?: IFormProps): Promise<any>;
  close(): void;
  forConfirm(middleware: IMiddleware<Form>): IFormDrawer;
  forCancel(middleware: IMiddleware<Form>): IFormDrawer;
}

export interface IDrawerProps extends DrawerProps {
  onClose?: (e: EventType) => void | boolean;
  loadingText?: React.ReactNode;
}

interface Env {
  host: HTMLDivElement;
  form?: Form;
  promise?: Promise<any>;
  openMiddlewares: IMiddleware<IFormProps>[];
  confirmMiddlewares: IMiddleware<Form>[];
  cancelMiddlewares: IMiddleware<Form>[];
}

export function FormDrawer(title: IDrawerProps, id: string, renderer: FormDrawerRenderer): IFormDrawer;
export function FormDrawer(title: IDrawerProps, id: FormDrawerRenderer): IFormDrawer;
export function FormDrawer(title: DrawerTitle, id: string, renderer: FormDrawerRenderer): IFormDrawer;
export function FormDrawer(title: DrawerTitle, id: FormDrawerRenderer): IFormDrawer;
export function FormDrawer(title: any, id: any, renderer?: any): IFormDrawer {
  if (isFn(id) || React.isValidElement(id)) {
    renderer = id;
    id = 'form-drawer';
  }
  const env: Env = {
    host: document.createElement('div'),
    form: undefined,
    promise: undefined,
    openMiddlewares: [],
    confirmMiddlewares: [],
    cancelMiddlewares: [],
  };
  const root = createPortalRoot(env.host, id);
  const props = getDrawerProps(title);
  const drawer = {
    width: '40%',
    ...props,
    onClose: (e: any) => {
      if (props?.onClose?.(e) !== false) {
        formDrawer.close();
      }
    },
    afterClose: () => {
      props?.afterClose?.();
      root.unmount();
    },
  };
  const DrawerContent = observer(() => <Fragment>{isFn(renderer) ? renderer(env.form) : renderer}</Fragment>);
  const renderDrawer = (visible = true, resolve?: () => any, reject?: () => any) => (
    <Observer>
      {() => (
        <FormProvider form={env.form!}>
          <Drawer
            {...drawer}
            visible={visible}
            confirmLoading={env.form?.submitting}
            onOk={async e => resolve?.()}
            onCancel={async e => reject?.()}
          >
            <DrawerContent />
          </Drawer>
        </FormProvider>
      )}
    </Observer>
  );

  document.body.appendChild(env.host);
  const formDrawer = {
    forOpen: (middleware: IMiddleware<IFormProps>) => {
      if (isFn(middleware)) {
        env.openMiddlewares.push(middleware);
      }
      return formDrawer;
    },
    forConfirm: (middleware: IMiddleware<Form>) => {
      if (isFn(middleware)) {
        env.confirmMiddlewares.push(middleware);
      }
      return formDrawer;
    },
    forCancel: (middleware: IMiddleware<Form>) => {
      if (isFn(middleware)) {
        env.cancelMiddlewares.push(middleware);
      }
      return formDrawer;
    },
    open: (props: IFormProps) => {
      if (env.promise) {
        return env.promise;
      }
      env.promise = new Promise(async (resolve, reject) => {
        try {
          props = await loading(drawer.loadingText, () => applyMiddleware(props, env.openMiddlewares));
          env.form = env.form || createForm(props);
        } catch (e) {
          reject(e);
        }
        root.render(() => renderDrawer(false));
        setTimeout(() => {
          root.render(() =>
            renderDrawer(
              true,
              () => {
                env.form
                  ?.submit(async () => {
                    await applyMiddleware(env.form, env.confirmMiddlewares);
                    resolve(toJS(env.form?.values));
                    formDrawer.close();
                  })
                  .catch(() => {});
              },
              async () => {
                await loading(drawer.loadingText, () => applyMiddleware(env.form, env.cancelMiddlewares));
                formDrawer.close();
              }
            )
          );
        }, 16);
      });
      return env.promise;
    },
    close: () => {
      if (!env.host) {
        return;
      }
      root.render(() => renderDrawer(false));
    },
  };
  return formDrawer;
}

const DrawerExtra: ReactFC = props => {
  const ref = useRef<HTMLDivElement>(null);
  const [extra, setExtra] = useState<HTMLDivElement>();
  const extraRef = useRef<HTMLDivElement>();
  const prefixCls = usePrefixCls('drawer');
  useLayoutEffect(() => {
    const content = ref.current?.closest(`.${prefixCls}-wrapper`)?.querySelector(`.${prefixCls}-header`);
    if (content) {
      if (!extraRef.current) {
        extraRef.current = content.querySelector(`.${prefixCls}-extra`) as HTMLDivElement;
        if (!extraRef.current) {
          extraRef.current = document.createElement('div');
          extraRef.current.classList.add(`${prefixCls}-extra`);
          content.appendChild(extraRef.current);
        }
      }
      setExtra(extraRef.current);
    }
  });

  extraRef.current = extra;

  return (
    <div ref={ref} style={{ display: 'none' }}>
      {extra && createPortal(props.children, extra)}
    </div>
  );
};

const DrawerFooter: ReactFC = props => {
  const ref = useRef<HTMLDivElement>(null);
  const [footer, setFooter] = useState<HTMLDivElement>();
  const footerRef = useRef<HTMLDivElement>();
  const prefixCls = usePrefixCls('drawer');
  useLayoutEffect(() => {
    const content = ref.current?.closest(`.${prefixCls}-wrapper`);
    if (content) {
      if (!footerRef.current) {
        footerRef.current = content.querySelector(`.${prefixCls}-footer`) as HTMLDivElement;
        if (!footerRef.current) {
          footerRef.current = document.createElement('div');
          footerRef.current.classList.add(`${prefixCls}-footer`);
          content.appendChild(footerRef.current);
        }
      }
      setFooter(footerRef.current);
    }
  });

  footerRef.current = footer;

  return (
    <div ref={ref} style={{ display: 'none' }}>
      {footer && createPortal(props.children, footer)}
    </div>
  );
};

FormDrawer.Extra = DrawerExtra;

FormDrawer.Footer = DrawerFooter;

FormDrawer.Portal = createPortalProvider('form-drawer');

export default FormDrawer;
